code.C:
#include <stdio.h>

int trailingZeroes(int n) {
    int ans = 0;
    while (n > 0) {
        n /= 5;
        ans += n;
    }
    return ans;
}

int main(void) {
    int n;
    if (scanf("[ %d ]", &n) == 1) {
        printf("%d\n", trailingZeroes(n));
    }
    return 0;
}

code.C++:
#include <bits/stdc++.h>
using namespace std;

class Solution {
public:
    int trailingZeroes(int n) {
        int ans = 0;
        while (n > 0) {
            n /= 5;
            ans += n;
        }
        return ans;
    }
};

int main() {
    string line;
    getline(cin, line);
    int n = stoi(line.substr(1, line.size() - 2));
    cout << Solution().trailingZeroes(n) << endl;
    return 0;
}

code.Java:
import java.io.*;

class Solution {
    public int trailingZeroes(int n) {
        int ans = 0;
        while (n > 0) {
            n /= 5;
            ans += n;
        }
        return ans;
    }
}

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine().trim();
        int n = Integer.parseInt(line.substring(1, line.length() - 1).trim());
        System.out.println(new Solution().trailingZeroes(n));
    }
}

