code.JavaScript:
'use strict';
const readline = require('readline');

/**
 * @param {number} n
 * @return {number}
 */
var trailingZeroes = function(n) {
    let ans = 0;
    while (n > 0) {
        n = Math.floor(n / 5);
        ans += n;
    }
    return ans;
};

const rl = readline.createInterface({ input: process.stdin });
rl.on('line', line => {
    const _args = JSON.parse(line.trim());
    const _result = trailingZeroes(_args[0]);
    console.log(JSON.stringify(_result));
    rl.close();
});

